"use strict";const t=require("./index.js");exports.approveTask=function(e,r){return t.request({url:"/workflow/task/"+e+"/approve",method:"POST",data:r})},exports.getDoneTasks=function(){return t.request({url:"/workflow/task/done",method:"GET"})},exports.getNotifications=function(e){return t.request({url:"/system/notification/list",method:"GET",data:e})},exports.getTaskDetail=function(e){return t.request({url:"/workflow/task/"+e,method:"GET"})},exports.getTodoTasks=function(){return t.request({url:"/workflow/task/todo",method:"GET"})},exports.getUnreadCount=function(){return t.request({url:"/system/notification/unread-count",method:"GET"})},exports.markAllRead=function(){return t.request({url:"/system/notification/read-all",method:"PUT"})},exports.markRead=function(e){return t.request({url:"/system/notification/read/"+e,method:"PUT"})},exports.rejectTask=function(e,r){return t.request({url:"/workflow/task/"+e+"/reject",method:"POST",data:r})};
